#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2; // tensor num for each queue

class KernelMambaReturnY {
public:
    __aicore__ inline KernelMambaReturnY() {}
    __aicore__ inline void Init(GM_ADDR y_diag, GM_ADDR y_off, GM_ADDR y, uint32_t totalLength, uint32_t tileNum)
    {
        this->blockLength = totalLength / AscendC::GetBlockNum();
        this->tileNum = tileNum;
        this->tileLength = this->blockLength / tileNum / BUFFER_NUM;

        yDiagGm.SetGlobalBuffer((__gm__ DTYPE_X *)y_diag + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);
        yOffGm.SetGlobalBuffer((__gm__ DTYPE_Y *)y_off + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);
        yGm.SetGlobalBuffer((__gm__ DTYPE_Z *)y + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);

        pipe.InitBuffer(inQueueYDiag, BUFFER_NUM, this->tileLength * sizeof(DTYPE_X));
        pipe.InitBuffer(inQueueYOff, BUFFER_NUM, this->tileLength * sizeof(DTYPE_Y));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, this->tileLength * sizeof(DTYPE_Z));
    }
    __aicore__ inline void Process()
    {
        int32_t loopCount = this->tileNum * BUFFER_NUM;
        for (int32_t i = 0; i < loopCount; i++) {
            CopyIn(i);
            Compute(i);
            CopyOut(i);
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t progress)
    {
        AscendC::LocalTensor<DTYPE_X> yDiagLocal = inQueueYDiag.AllocTensor<DTYPE_X>();
        AscendC::LocalTensor<DTYPE_Y> yOffLocal = inQueueYOff.AllocTensor<DTYPE_Y>();
        AscendC::DataCopy(yDiagLocal, yDiagGm[progress * this->tileLength], this->tileLength);
        AscendC::DataCopy(yOffLocal, yOffGm[progress * this->tileLength], this->tileLength);
        inQueueYDiag.EnQue(yDiagLocal);
        inQueueYOff.EnQue(yOffLocal);
    }
    __aicore__ inline void Compute(int32_t /*progress*/)
    {
        AscendC::LocalTensor<DTYPE_X> yDiagLocal = inQueueYDiag.DeQue<DTYPE_X>();
        AscendC::LocalTensor<DTYPE_Y> yOffLocal = inQueueYOff.DeQue<DTYPE_Y>();
        AscendC::LocalTensor<DTYPE_Z> yLocal = outQueueY.AllocTensor<DTYPE_Z>();
        AscendC::Add(yLocal, yDiagLocal, yOffLocal, this->tileLength);
        outQueueY.EnQue<DTYPE_Z>(yLocal);
        inQueueYDiag.FreeTensor(yDiagLocal);
        inQueueYOff.FreeTensor(yOffLocal);
    }
    __aicore__ inline void CopyOut(int32_t progress)
    {
        AscendC::LocalTensor<DTYPE_Z> yLocal = outQueueY.DeQue<DTYPE_Z>();
        AscendC::DataCopy(yGm[progress * this->tileLength], yLocal, this->tileLength);
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueYDiag, inQueueYOff;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::GlobalTensor<DTYPE_X> yDiagGm;
    AscendC::GlobalTensor<DTYPE_Y> yOffGm;
    AscendC::GlobalTensor<DTYPE_Z> yGm;
    uint32_t blockLength;
    uint32_t tileNum;
    uint32_t tileLength;
};

extern "C" __global__ __aicore__ void mamba_return_y_custom(GM_ADDR y_diag, GM_ADDR y_off, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling) {
    GET_TILING_DATA(tiling_data, tiling);
    KernelMambaReturnY op;
    op.Init(y_diag, y_off, y, tiling_data.totalLength, tiling_data.tileNum);
    op.Process();
}
"""

